// Замкнутые циклы: для советов, с момента которых прошло >= 7 дней,
// сравниваем 7 дней ДО выдачи и 7 дней ПОСЛЕ по метрике действия.
const action_loops = [];
for (const rec of recsWithActions) {
  if (shiftDays(rec.date, 7) > lastDate) continue;   // неделя ещё не прошла
  for (const a of rec.parsed.actions) {
    if (!a.metric) continue;
    const cfg = METRICS.find(m => m.key === a.metric);
    if (!cfg) continue;
    const before = meanBetween(cfg.col, shiftDays(rec.date, -6), rec.date);
    const after  = meanBetween(cfg.col, shiftDays(rec.date, 1), shiftDays(rec.date, 7));
    if (!before || !after) continue;
    const delta = after.mean - before.mean;
    const j = judge(cfg.direction, delta, cfg.minAbsDelta);
    action_loops.push({
      issued: rec.date,
      title: a.title,
      metric: a.metric,
      metric_label: cfg.label,
      unit: cfg.unit,
      before: rSmart(before.mean),
      after: rSmart(after.mean),
      delta_abs: rSmart(delta),
      judgment: j,
      status: j === 'good' ? 'сработало' : j === 'bad' ? 'стало хуже' : 'без изменений',
      expect: a.expect || '',
    });
  }
  if (action_loops.length >= 3) break;
}

